(function(E){ const x = E["ai-m1"] = E["ai-m1"] || {units:{}}; x.units["ai-2"] = {"grammar":{"id":"c-ai-2-g","level":"B1","course":"ai-internet","unit":"ai-2","title":"Describing a problem: I can't + verb, the message says","titleTr":"Sorun anlatmak: I can't + fiil, the message says","titleFa":"مشکل را توضیح بده: I can't و the message says","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I can't + verb","I can't upload this file."],["The message says \"...\"","The message says \"limit reached\"."],["It isn't + adjective","It isn't available here."]]},"wrong":"I can't to upload the file.","right":"I can't upload the file.","blank":{"sentence":"I can't ___ a PDF to this chat.","word":"attach","distractors":["to attach","attaching"]},"wrong2":"The message tells \"file too large\".","right2":"The message says \"file too large\".","blank2":{"sentence":"The message ___ \"something went wrong\".","word":"says","distractors":["tells","speaks"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Use I can't + base verb for the problem.","tr":"Sorun için I can't + yalın fiil kullan.","fa":"برای گفتن مشکل، بعد از I can't شکل ساده‌ی فعل بیاور.","ex":"I can't open the chat."},{"en":"Quote the exact words of the message.","tr":"Mesajın tam kelimelerini aktar.","fa":"کلمه‌های دقیق پیام را نقل کن.","ex":"The message says \"try again later\"."}],"test":{"en":"Is there -ing or to after can't? Remove it.","tr":"can't'ten sonra -ing ya da to var mı? Çıkar.","fa":"بعد از can't فعل با ‎-ing یا to آمده؟ حذفش کن."}},"errorWatch":[{"find":["can't to"],"fix":{"en":"After can't, use the base verb: \"I can't upload\".","tr":"can't'ten sonra yalın fiil gelir: \"I can't upload\".","fa":"بعد از can't شکل ساده‌ی فعل بیاور: «I can't upload»."}}]},"b2":{"id":"c-ai-2-b2","level":"B2","course":"ai-internet","unit":"ai-2","track":"B2","title":"Polite questions to support: could you tell me + statement order","titleTr":"Destek için nazik sorular: could you tell me + düz sıra","titleFa":"سؤال مؤدبانه از پشتیبانی: could you tell me و بعد ترتیب جمله‌ی خبری","formsTable":{"headers":{"en":["Direct","Polite"],"tr":["Doğrudan","Nazik"],"fa":["مستقیم","مؤدبانه"]},"rows":[["What is the limit?","Could you tell me what the limit is?"],["Why is it blocked?","Could you tell me why it is blocked?"]]},"wrong":"Could you tell me what is the limit?","right":"Could you tell me what the limit is?","blank":{"sentence":"Could you tell me why the file ___?","word":"was rejected","distractors":["rejected was","did reject"]},"wrong2":"Could you tell me is it supported?","right2":"Could you tell me if it is supported?","blank2":{"sentence":"Could you tell me ___ this plan includes voice?","word":"if","distractors":["does","is"]},"expParts":{"tryFrom":"blank","rule":[{"en":"After could you tell me, use statement order.","tr":"could you tell me'den sonra düz sıra kullan.","fa":"بعد از could you tell me ترتیب جمله‌ی خبری بیاور.","ex":"Could you tell me what the limit is?"},{"en":"Use if when there is no question word.","tr":"Soru kelimesi yoksa if kullan.","fa":"اگر کلمه‌ی پرسشی نیست از if استفاده کن.","ex":"Could you tell me if it is supported?"}],"test":{"en":"Is the verb at the end? Then the order is right.","tr":"Fiil sonda mı? O zaman sıra doğru.","fa":"فعل آخر آمده؟ پس ترتیب درست است."}},"errorWatch":[{"find":["tell me what is the"],"fix":{"en":"After could you tell me, use statement order.","tr":"could you tell me'den sonra düz sıra kullan.","fa":"بعد از could you tell me ترتیب خبری بیاور."}}],"useIn":{"en":"B2: end your help request with one polite question in statement order.","tr":"B2: Yardım isteğini düz sıralı nazik bir soruyla bitir.","fa":"B2: درخواست کمکت را با یک سؤال مؤدبانه با ترتیب خبری تمام کن."},"exitItem":{"from":"ai-2","kind":"mcq","prompt":"Which question is correct?","options":["Could you tell me what the limit is?","Could you tell me what is the limit?","Could you tell what the limit?"],"correct":0,"why":{"en":"'Could you tell me what the limit is?' keeps statement order inside the question. 'What is the limit' is question order, and the third drops me and is.","tr":"'Could you tell me what the limit is?' sorunun içinde düz sırayı korur. 'What is the limit' soru sırasıdır; üçüncüsü me ve is'i düşürür.","fa":"«Could you tell me what the limit is?» درست است، چون داخل سؤال ترتیب خبری حفظ شده. what is the limit ترتیب سؤالی است و گزینه‌ی سوم me و is را ندارد."}}},"vocab":{"id":"c-ai-2-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-2","goals":["career"],"title":{"en":"The English of tool screens","tr":"Araç ekranlarının İngilizcesi","fa":"انگلیسی صفحه‌ی ابزارها"},"cards":[{"word":"New chat","sentence":"Press New chat for a different topic.","meaning":{"en":"Start again, with no earlier messages in this chat","tr":"Yeniden başla, bu sohbette önceki mesajlar olmadan","fa":"از نو شروع کن، بدون پیام‌های قبلی در این چت"}},{"word":"Sources","sentence":"Open Sources and read the pages.","meaning":{"en":"The list of links behind an answer","tr":"Bir yanıtın dayandığı bağlantıların listesi","fa":"فهرست لینک‌هایی که جواب بر اساس آن‌هاست"}},{"word":"Temporary Chat","sentence":"A Temporary Chat is not a place for secrets.","meaning":{"en":"A chat that stays out of your history and isn't used to improve the models","tr":"Geçmişinde görünmeyen ve modelleri geliştirmek için kullanılmayan sohbet","fa":"چتی که در تاریخچه‌ات نمی‌ماند و برای بهتر کردن مدل‌ها استفاده نمی‌شود"}},{"word":"upload","sentence":"You can upload a file to the chat.","meaning":{"en":"To send a file from your device to a tool.","tr":"Cihazından araca dosya göndermek.","fa":"فرستادن فایل از دستگاهت به ابزار."}},{"word":"limit","sentence":"You have reached your limit for today.","meaning":{"en":"The most you can use.","tr":"Kullanabileceğin en fazla miktar.","fa":"بیشترین مقداری که می‌توانی استفاده کنی."}},{"word":"supported","sentence":"This file type is not supported.","meaning":{"en":"Accepted and working in the tool.","tr":"Araçta kabul edilen ve çalışan.","fa":"ابزار آن را می‌پذیرد و با آن کار می‌کند."}}]},"judge":{"id":"c-ai-2-j","course":"ai-internet","unit":"ai-2","type":"judge","title":{"en":"What should you do?","tr":"Ne yapmalısın?","fa":"چه باید بکنی؟"},"prompt":"Read each message and choose what to do.","parts":["Wait","Make the file smaller","Try again","Use the examples"],"instruction":{"en":"Choose one action for each message.","tr":"Her mesaj için bir eylem seç.","fa":"برای هر پیام یک کار را انتخاب کن."},"mode":"single","screen":{"id":"scr-chatgpt-1","src":"courses/ai-internet/assets/scr-chatgpt-1.webp?v=edc2d02c3d","alt":"Our drawing of a ChatGPT-style chat screen, November 2026, not a screenshot. New chat at the top, Sources under an answer, the message box at the bottom."},"items":[{"by":"Example message","answer":"Limit reached. Try again later.","present":["Wait"],"fix":{"en":"You used too much for now. Wait, then try later.","tr":"Şimdilik çok kullandın. Bekle, sonra dene.","fa":"فعلاً زیاد استفاده کرده‌ای. صبر کن و بعداً امتحان کن."}},{"by":"Example message","answer":"File too large.","present":["Make the file smaller"],"fix":{"en":"Make it smaller, or paste a part of it.","tr":"Küçült ya da bir bölümünü yapıştır.","fa":"کوچکش کن یا بخشی از آن را بچسبان."}},{"by":"Example message","answer":"Something went wrong.","present":["Try again"],"fix":{"en":"The tool had a problem. Try again.","tr":"Araçta sorun oldu. Yeniden dene.","fa":"ابزار دچار مشکل شده. دوباره امتحان کن."}},{"by":"Example message","answer":"Not available in your region.","present":["Use the examples"],"fix":{"en":"In this course, continue with the fixed examples.","tr":"Bu kursta sabit örneklerle devam et.","fa":"در این دوره با نمونه‌های آماده ادامه بده."}}]},"speaking":{"id":"ai-2","course":"ai-internet","unit":"ai-2","topic":{"en":"Explain a message to a colleague","tr":"Bir mesajı meslektaşına açıkla","fa":"یک پیام را برای همکارت توضیح بده"},"warmup":{"en":"What does \"try again later\" mean on a screen?","tr":"Ekranda \"try again later\" ne demek?","fa":"«try again later» روی صفحه یعنی چه؟"},"questions":[{"en":"A colleague sees \"Limit reached\". Say what it means and what to do.","tr":"Bir meslektaşın \"Limit reached\" görüyor. Ne demek olduğunu ve ne yapması gerektiğini söyle.","fa":"همکارت «Limit reached» را می‌بیند. بگو یعنی چه و چه باید بکند."},{"en":"A colleague can't upload a 40-page report. The screen says \"File too large\". Tell them what to do.","tr":"Bir meslektaşın 40 sayfalık raporu yükleyemiyor. Ekranda \"File too large\" yazıyor. Ne yapması gerektiğini söyle.","fa":"همکارت نمی‌تواند گزارش ۴۰ صفحه‌ای را آپلود کند. روی صفحه نوشته «File too large». به او بگو چه کند."},{"en":"Say a help request aloud: what you did, what the message says, and one question.","tr":"Yardım isteğini yüksek sesle söyle: ne yaptın, mesaj ne diyor ve bir soru.","fa":"درخواست کمک را بلند بگو: چه کردی، پیام چه می‌گوید و یک سؤال."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"It means that...","meaning":{"en":"Explains a message.","tr":"Bir mesajı açıklar.","fa":"یک پیام را توضیح می‌دهد."}},{"phrase":"You can wait and...","meaning":{"en":"Gives the next step.","tr":"Sonraki adımı söyler.","fa":"قدم بعدی را می‌گوید."}},{"phrase":"The message says...","meaning":{"en":"Quotes the screen.","tr":"Ekrandakini aktarır.","fa":"نوشته‌ی روی صفحه را نقل می‌کند."}}],"model":"That message means that you used too much for now. It doesn't mean your work is lost. You can wait and try again later, or you can do the job in a different tool. I would copy your prompt first, so you don't have to write it twice when it works again.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I said what it means and what to do next.","tr":"Ne demek olduğunu ve sonra ne yapılacağını söyledim.","fa":"گفتم یعنی چه و قدم بعدی چیست."}]},"writing":{"id":"c-ai-2-w","title":{"en":"Write a help request","tr":"Yardım isteği yaz","fa":"درخواست کمک بنویس"},"course":"ai-internet","unit":"ai-2","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Your file will not upload. The screen says \"File too large\". The file is 45 MB. Write a short help request.","tr":"Dosyan yüklenmiyor. Ekranda \"File too large\" yazıyor. Dosya 45 MB. Kısa bir yardım isteği yaz.","fa":"فایلت آپلود نمی‌شود. روی صفحه نوشته «File too large». فایل ۴۵ مگابایت است. یک درخواست کمک کوتاه بنویس."},"model":"Hello. I can't upload a report to the chat. The message says \"File too large\". The file is 45 MB. Could you tell me what the limit is, and whether I can upload the file in parts?","frame":"Hello. I can't ___. The message says \"___\". The file is ___. What is ___?","words":[{"word":"I can't"},{"word":"The message says"}],"minWords":20,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Ask two polite questions in statement order.","tr":"B2 yolu: hazır çerçeve yok. Düz sıralı iki nazik soru sor.","fa":"مسیر B2: چارچوب آماده نداری. دو سؤال مؤدبانه با ترتیب خبری بپرس."},"own":{"en":"Now write one help request about a real problem you have had with any website or app.","tr":"Şimdi herhangi bir site ya da uygulamayla yaşadığın gerçek bir sorun için yardım isteği yaz.","fa":"حالا درباره‌ی مشکلی واقعی که با یک سایت یا اپلیکیشن داشته‌ای یک درخواست کمک بنویس."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Open your tool and find the words New chat and Settings. Write down one message you see.","tr":"Aracını aç, New chat ve Settings kelimelerini bul. Gördüğün bir mesajı yaz.","fa":"ابزارت را باز کن و New chat و Settings را پیدا کن. یکی از پیام‌هایی را که می‌بینی بنویس."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the example messages in this lesson. The task is the same.","tr":"Bu dersteki örnek mesajları kullan. Görev aynı.","fa":"از پیام‌های نمونه‌ی همین درس استفاده کن. تمرین فرقی نمی‌کند."},"noTool":true}]},"exit":{"id":"c-ai-2-x","course":"ai-internet","unit":"ai-2","type":"exit","items":[{"from":"ai-2","kind":"mcq","prompt":"You want ChatGPT to start again, with no earlier messages. What do you press?","options":["Settings","Sources","New chat"],"correct":2,"why":{"en":"New chat: it opens an empty conversation, so earlier messages don't affect the answer. Settings changes how the app works, but it doesn't start again.","tr":"New chat: boş bir sohbet açar; önceki mesajlar cevabı etkilemez. Settings uygulamanın ayarlarını değiştirir ama baştan başlatmaz.","fa":"New chat درست است، چون یک گفت‌وگوی خالی باز می‌کند و پیام‌های قبلی روی جواب اثر نمی‌گذارند. Settings تنظیمات برنامه را عوض می‌کند، ولی از اول شروع نمی‌کند."},"point":1},{"from":"ai-2","kind":"mcq","prompt":"The screen says \"Too many requests\". What is the best next step?","options":["Make a new account.","Write a longer prompt.","Wait and try later."],"correct":2,"why":{"en":"Wait and try later: the message means you have used your limit for now, and it comes back with time. A new account only hides the problem and may break the rules.","tr":"Wait and try later: mesaj şimdilik sınırını doldurduğun anlamına gelir; sınır zamanla yenilenir. Yeni hesap açmak sorunu yalnızca gizler ve kurallara aykırı olabilir.","fa":"Wait and try later درست است، چون این پیام یعنی فعلاً سهمیه‌ات تمام شده و بعد از مدتی برمی‌گردد. ساختن حساب تازه فقط مشکل را پنهان می‌کند و ممکن است خلاف قوانین باشد."},"point":4},{"from":"ai-2","kind":"blank","prompt":"I ___ open the file. The message says \"not supported\".","options":["can't","can't to","don't can"],"correct":0,"why":{"en":"can't: after can't, use the base verb with no to. 'Don't can' is a common slip, but can never takes do.","tr":"can't: can't'tan sonra to olmadan yalın fiil gelir. 'Don't can' sık yapılan bir hatadır, ama can hiçbir zaman do almaz.","fa":"can't درست است، چون بعد از can't فعل ساده بدون to می‌آید. don't can اشتباه رایجی است، ولی can هیچ‌وقت با do نمی‌آید."},"point":6},{"from":"ai-1","kind":"mcq","prompt":"Which sentence recommends a tool correctly?","options":["It is good at summarising.","It is good summarise.","It is good at to summarise."],"correct":0,"why":{"en":"It is good at summarising: good at is followed by -ing. 'Good at to summarise' adds to, and 'good summarise' drops at.","tr":"It is good at summarising: good at'ten sonra -ing gelir. 'Good at to summarise' fazladan to ekler; 'good summarise' ise at'i düşürür.","fa":"It is good at summarising درست است، چون بعد از good at فعل ing‌دار می‌آید. good at to summarise یک to اضافه دارد و good summarise کلمه‌ی at را جا انداخته."},"point":5},{"from":"ai-1","kind":"mcq","prompt":"You need links to sources. Which kind of tool do you start with?","options":["AI search","A spreadsheet","An image maker"],"correct":0,"why":{"en":"AI search: it answers with links you can open and check. An image maker makes pictures, and a spreadsheet holds numbers; neither finds sources.","tr":"AI search: açıp kontrol edebileceğin bağlantılarla cevap verir. Resim aracı görsel yapar, tablo programı sayıları tutar; ikisi de kaynak bulmaz.","fa":"AI search درست است، چون با لینک‌هایی جواب می‌دهد که می‌توانی باز و بررسی کنی. ابزار تصویرسازی عکس می‌سازد و صفحه‌گسترده عدد نگه می‌دارد؛ هیچ‌کدام منبع پیدا نمی‌کنند."},"point":3},{"from":"ai-1","kind":"blank","prompt":"If you work in Gmail, ___ Gemini.","options":["trying","try","tried"],"correct":1,"why":{"en":"try: in 'if you..., try...' the second part is an instruction, so it starts with the base verb. 'Trying' and 'tried' don't give an instruction.","tr":"try: 'if you..., try...' kalıbında ikinci kısım bir talimattır, bu yüzden yalın fiille başlar. 'Trying' ve 'tried' talimat vermez.","fa":"try درست است، چون در الگوی if you..., try... بخش دوم دستور است و با فعل ساده شروع می‌شود. trying و tried دستور نمی‌دهند."},"point":5}]},"explain":{"id":"c-ai-2-e","course":"ai-internet","unit":"ai-2","type":"explain","level":"B1","title":{"en":"ChatGPT: read the screen","tr":"ChatGPT: ekranı oku","fa":"⁨ChatGPT⁩: صفحه را بخوان"},"objective":{"en":"After this lesson, you can use ChatGPT's main screen words, understand its messages and write a help request.","tr":"Bu dersin sonunda ChatGPT'nin ana ekran kelimelerini kullanabilecek, mesajlarını anlayabilecek ve yardım isteği yazabileceksin.","fa":"بعد از این درس می‌توانی کلمه‌های اصلی صفحه‌ی ⁨ChatGPT⁩ را به کار ببری، پیام‌هایش را بفهمی و درخواست کمک بنویسی."},"hook":{"en":"When a tool stops working, the screen usually says why and what to do next. If you can read that message, you can solve most problems yourself.","tr":"Bir araç çalışmayınca ekran genelde nedenini ve sonra ne yapılacağını söyler. O mesajı okuyabilirsen çoğu sorunu kendin çözersin.","fa":"وقتی ابزاری کار نمی‌کند، معمولاً روی صفحه نوشته چرا و بعدش چه باید بکنی. اگر بتوانی این پیام را بخوانی، بیشتر مشکل‌ها را خودت حل می‌کنی."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"6"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What ChatGPT is","tr":"ChatGPT nedir","fa":"⁨ChatGPT⁩ چیست"},"body":{"en":"ChatGPT is a general AI assistant made by the company OpenAI. You write a message and it answers in the same chat. It can write, explain, search the web, read files and make images.","tr":"ChatGPT, OpenAI şirketinin yaptığı genel bir yapay zekâ asistanıdır. Bir mesaj yazarsın, aynı sohbette yanıt verir. Yazı yazabilir, açıklayabilir, web'de arama yapabilir, dosya okuyabilir ve görsel üretebilir.","fa":"⁨ChatGPT⁩ یک دستیار عمومی هوش مصنوعی است که شرکت ⁨OpenAI⁩ آن را ساخته. پیامی می‌نویسی و در همان چت جواب می‌دهد. می‌تواند بنویسد، توضیح بدهد، در وب جست‌وجو کند، فایل بخواند و تصویر بسازد."},"steps":[{"en":"It remembers what you said earlier in the same chat, so you can simply ask for changes.","tr":"Aynı sohbette daha önce söylediklerini hatırlar; değişikliği doğrudan isteyebilirsin.","fa":"حرف‌های قبلی‌ات را در همان چت به یاد دارد، پس می‌توانی به‌سادگی تغییر بخواهی.","ex":"Shorter, please. Keep the date."},{"en":"New chat starts with a clean page. Use it for a new topic.","tr":"New chat temiz bir sayfayla başlar. Yeni bir konu için kullan.","fa":"⁨New chat⁩ با صفحه‌ای خالی شروع می‌شود. برای موضوع جدید از آن استفاده کن.","ex":"New chat"}],"tip":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."}},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What it is good for, and not","tr":"Neye yarar, neye yaramaz","fa":"به چه کاری می‌آید و به چه کاری نه"},"steps":[{"en":"First drafts and rewrites of emails and short texts","tr":"E-posta ve kısa metinlerin ilk taslakları ve yeniden yazımı","fa":"پیش‌نویس اول و بازنویسی ایمیل و متن‌های کوتاه","ex":"Rewrite this email in plain English."},{"en":"Explaining a hard text in simple words","tr":"Zor bir metni basit kelimelerle açıklamak","fa":"توضیح دادن یک متن سخت با کلمه‌های ساده","ex":"Explain this contract line in simple words."},{"en":"Not the best: a fact you won't check. OpenAI warns it can give wrong facts and invented references.","tr":"En iyisi değil: Kontrol etmeyeceğin bir bilgi. OpenAI, yanlış bilgi ve uydurma kaynak verebileceği konusunda uyarıyor.","fa":"بهترین گزینه نیست: اطلاعاتی که قرار نیست بررسی‌اش کنی. خود ⁨OpenAI⁩ هشدار می‌دهد که ممکن است اطلاعات غلط و منبع ساختگی بدهد.","ex":"Invented references can look real."},{"en":"Not the best: private customer or company information","tr":"En iyisi değil: Özel müşteri ya da şirket bilgileri","fa":"بهترین گزینه نیست: اطلاعات خصوصی مشتری یا شرکت","ex":"Customer lists, contracts, passwords"}]},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"How to start","tr":"Nasıl başlanır","fa":"چطور شروع کنی"},"steps":[{"en":"Go to chatgpt.com.","tr":"chatgpt.com adresine git.","fa":"به ⁨chatgpt.com⁩ برو."},{"en":"Sign up or log in.","tr":"Kaydol ya da giriş yap.","fa":"ثبت‌نام کن یا وارد شو."},{"en":"Type in the message box and send.","tr":"Mesaj kutusuna yaz ve gönder.","fa":"در کادر پیام بنویس و بفرست."},{"en":"Read the answer. Ask for changes in the same chat.","tr":"Yanıtı oku. Değişiklikleri aynı sohbette iste.","fa":"جواب را بخوان. تغییرها را در همان چت بخواه."}],"phrases":[{"phrase":"Rewrite this email in plain English for a customer who is not technical.\nKeep every number and date. Under 100 words.\nThen list what you changed.\nEmail: [paste the email, with private details removed]","meaning":{"en":"It is good at rewriting, and the last line lets you check its changes.","tr":"Yeniden yazmada iyidir, son satır da değişikliklerini kontrol etmeni sağlar.","fa":"در بازنویسی خوب است و خط آخر کمک می‌کند تغییرهایش را بررسی کنی."},"copy":true}],"tip":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}},{"head":{"en":"Five messages, and what to do","tr":"Beş mesaj ve ne yapmalı","fa":"پنج پیام و کاری که باید بکنی"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"tip":{"en":"A message tells you what to do next, so read it before you try again. Exact words can differ by tool.","tr":"Mesaj sonra ne yapacağını söyler; yeniden denemeden önce oku. Tam kelimeler araca göre değişebilir.","fa":"پیام به تو می‌گوید قدم بعدی چیست، پس پیش از تلاش دوباره آن را بخوان. کلمه‌های دقیق ممکن است در هر ابزار فرق کند."},"steps":[{"en":"You used too much for now. Wait and try later.","tr":"Şimdilik çok kullandın. Bekle, sonra yeniden dene.","fa":"فعلاً زیاد استفاده کرده‌ای. صبر کن و بعداً دوباره امتحان کن.","ex":"Limit reached / Too many requests"},{"en":"The file is over the limit. Make it smaller or paste a part.","tr":"Dosya sınırın üstünde. Küçült ya da bir bölümünü yapıştır.","fa":"فایل از حد مجاز بزرگ‌تر است. کوچکش کن یا بخشی از آن را بچسبان.","ex":"File too large"},{"en":"The tool had a problem. Try again.","tr":"Araçta bir sorun oldu. Yeniden dene.","fa":"ابزار دچار مشکل شده. دوباره امتحان کن.","ex":"Something went wrong"},{"en":"The tool isn't offered there. In this course, continue with the fixed examples.","tr":"Araç orada sunulmuyor. Bu kursta sabit örneklerle devam et.","fa":"این ابزار در کشور تو ارائه نمی‌شود. در این دوره با نمونه‌های آماده ادامه بده.","ex":"Not available in your region"},{"en":"The tool refused the request. Say honestly what you need, or do the task another way.","tr":"Araç isteği reddetti. Neye ihtiyacın olduğunu dürüstçe söyle ya da işi başka yoldan yap.","fa":"ابزار درخواست را رد کرده. صادقانه بگو چه می‌خواهی یا کار را از راه دیگری انجام بده.","ex":"Blocked by policy / I can't help with that"}]},{"head":{"en":"Get help in English","tr":"İngilizce yardım al","fa":"به انگلیسی کمک بگیر"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"Search a help page with key words, not a whole sentence.","tr":"Yardım sayfasında tam cümleyle değil, anahtar kelimelerle ara.","fa":"در صفحه‌ی راهنما با کلمه‌های کلیدی بگرد، نه با جمله‌ی کامل.","ex":"how to delete a chat"},{"en":"In a help request, say what you did, what the screen says and what you need. Then nobody has to ask you back.","tr":"Yardım isteğinde ne yaptığını, ekranda ne yazdığını ve neye ihtiyacın olduğunu söyle. Böylece kimse sana geri sormak zorunda kalmaz.","fa":"در درخواست کمک بگو چه کردی، روی صفحه چه نوشته و چه می‌خواهی. این‌طوری لازم نیست کسی دوباره از تو بپرسد.","ex":"I can't upload a PDF. The message says \"file too large\". What is the limit?"}],"phrases":[{"phrase":"Explain this message in simple English. What should I do next?\nMessage: [paste the message]","meaning":{"en":"Copy this when a message is not clear. It works in any assistant.","tr":"Bir mesaj anlaşılmadığında bunu kopyala. Her asistanda işe yarar.","fa":"وقتی پیامی روشن نیست این را کپی کن. در هر دستیاری کار می‌کند."},"copy":true}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Describing a problem: I can't + verb, the message says","tr":"Sorun anlatmak: I can't + fiil, the message says","fa":"مشکل را توضیح بده: ⁨I can't⁩ و ⁨the message says⁩"},"steps":[{"en":"Use I can't + base verb for the problem.","tr":"Sorun için I can't + yalın fiil kullan.","fa":"برای گفتن مشکل، بعد از ⁨I can't⁩ شکل ساده‌ی فعل بیاور.","ex":"I can't open the chat."},{"en":"Quote the exact words of the message.","tr":"Mesajın tam kelimelerini aktar.","fa":"کلمه‌های دقیق پیام را نقل کن.","ex":"The message says \"try again later\"."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I can't + verb","I can't upload this file."],["The message says \"...\"","The message says \"limit reached\"."],["It isn't + adjective","It isn't available here."]]},"wrong":"I can't to open the file.","right":"I can't open the file."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Write a help request","tr":"Yardım isteği yaz","fa":"درخواست کمک بنویس"},"item":"It doesn't work. Help!\nWhat happened: you can't upload a 30 MB PDF. The message says \"file too large\".","answer":"I can't upload a PDF. The message says \"file too large\". The file is 30 MB. What is the limit?","walk":[{"en":"Say what you tried, with I can't.","tr":"Ne denediğini I can't ile söyle.","fa":"با ⁨I can't⁩ بگو چه کاری را امتحان کردی."},{"en":"Quote the message.","tr":"Mesajı aktar.","fa":"پیام را نقل کن."},{"en":"Give one fact, then ask one question.","tr":"Bir bilgi ver, sonra bir soru sor.","fa":"یک نکته‌ی مشخص بگو و بعد یک سؤال بپرس."}],"why":{"en":"The first version gives support nothing to work with. The second says what happened and quotes the message, so they can answer at once.","tr":"İlk sürümde destek ekibinin kullanacağı bir şey yok. İkincisi ne olduğunu söyler ve mesajı aktarır, böylece hemen yanıt verebilirler.","fa":"نسخه‌ی اول چیزی به پشتیبانی نمی‌دهد که با آن کار کند. نسخه‌ی دوم می‌گوید چه شده و پیام را نقل می‌کند، پس می‌توانند فوری جواب بدهند."}},"quick":{"prompt":"ChatGPT wrote your email, but it is too long. What do you do?","options":["Write \"Shorter, please\" in the same chat.","Press New chat and paste it all again.","Look for a length button in Settings."],"correct":0,"why":{"en":"It remembers the chat, so just ask for the change.","tr":"Sohbeti hatırlar, bu yüzden değişikliği doğrudan iste.","fa":"چت را به یاد دارد، پس فقط تغییر را بخواه."}},"quickAfter":3,"remember":{"en":"Read the message first, because it usually tells you what to do. You can now act on the main messages and write a help request that gets a useful answer.","tr":"Önce mesajı oku, çünkü genelde ne yapacağını söyler. Artık ana mesajlara göre davranabilir ve işe yarar yanıt alan bir yardım isteği yazabilirsin.","fa":"اول پیام را بخوان، چون معمولاً می‌گوید چه کنی. حالا می‌توانی طبق پیام‌های اصلی عمل کنی و درخواست کمکی بنویسی که جواب مفید می‌گیرد."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Polite questions to support: could you tell me + statement order","tr":"Destek için nazik sorular: could you tell me + düz sıra","fa":"سؤال مؤدبانه از پشتیبانی: ⁨could you tell me⁩ و بعد ترتیب جمله‌ی خبری"},"steps":[{"en":"After could you tell me, use statement order.","tr":"could you tell me'den sonra düz sıra kullan.","fa":"بعد از ⁨could you tell me⁩ ترتیب جمله‌ی خبری بیاور.","ex":"Could you tell me what the limit is?"},{"en":"Use if when there is no question word.","tr":"Soru kelimesi yoksa if kullan.","fa":"اگر کلمه‌ی پرسشی نیست از ⁨if⁩ استفاده کن.","ex":"Could you tell me if it is supported?"}],"table":{"headers":{"en":["Direct","Polite"],"tr":["Doğrudan","Nazik"],"fa":["مستقیم","مؤدبانه"]},"rows":[["What is the limit?","Could you tell me what the limit is?"],["Why is it blocked?","Could you tell me why it is blocked?"]]},"body":{"en":"B2: end your help request with one polite question in statement order.","tr":"B2: Yardım isteğini düz sıralı nazik bir soruyla bitir.","fa":"⁨B2⁩: درخواست کمکت را با یک سؤال مؤدبانه با ترتیب خبری تمام کن."}},"tool":"chatgpt"}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
